<?php
namespace App\Http\Controllers;
use App\Models\{WebhookEvent,Payment};use App\Services\{PaymentGatewayManager,PaymentService};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class WebhookController extends Controller {public function handle(Request $r,string $gateway,PaymentService $service){$raw=$r->getContent();$result=app(PaymentGatewayManager::class)->driver($gateway)->handleWebhook($raw,$r->headers->all());$event=DB::transaction(function()use($gateway,$result,$raw){return WebhookEvent::firstOrCreate(['gateway'=>$gateway,'payload_hash'=>hash('sha256',$raw)],['event_id'=>$result['event_id'],'event_type'=>$result['event_type'],'payload'=>$result['payload']]);});if($event->wasRecentlyCreated){$ref=$result['payload']['payload']['payment']['entity']['order_id']??$result['payload']['ORDERID']??null;if($ref&&($payment=Payment::where('reference',$ref)->first()))$service->markSuccessful($payment,$result['payload']['payload']['payment']['entity']['id']??$result['payload']['TXNID']??null,$result['payload']);$event->update(['processed_at'=>now()]);}return response()->json(['ok'=>true]);}}
